fn loop_access_array(k: usize) {
    let mut start = 0usize;
    while start < 4 {
        let _: u16 = CARRAY[k];
        start += 1;
    }
}

fn loop_array_len(b: bool) {
    let buf = [0u8; 4];
    let _: usize = buf.len();

    while b {
        let _ = buf.len();
    }
}

fn loop_array_len_write(b0: bool, b1: bool) {
    let mut buf = [0u8; 4];
    let _: usize = buf.len();

    while b0 {
        if b1 {
            write(&mut buf);
        }
    }
}

fn read_global_loop(b: bool, n_rows: usize) {
    debug_assert!(n_rows <= MAX_NROWS);
    while b {}
}

fn mut_loop_len(_: &mut u32, b: bool) {
    let buf = [0u8; 4];

    while b {
        debug_assert!(0 <= buf.len());
    }
}

fn test(b0: bool, b1: bool) {
    let mut buf = [0u8; 4];
    let _ = buf.len();

    while b0 {
        if b1 {
            write(&mut buf);
        }

        let _ = read(&buf);
    }
}

fn loop_consume_u32(params: &WrapperU32) {
    let x = params.x;

    for i in 0..32 {
        consume_u32(x);
    }
}
